"""Convert an amount in minor units with a Decimal rate; returns minor units.

Rounds toward negative infinity (ROUND_FLOOR) so a conversion never credits
more than the rate allows. This intentionally differs from tax rounding.
"""
if not isinstance(amount_cents, int):
    raise TypeError("amount_cents must be an int")
if not isinstance(rate, Decimal):
    raise TypeError("rate must be a Decimal")
converted = Decimal(amount_cents) * rate
return int(converted.to_integral_value(rounding=ROUND_FLOOR))

